import axios from 'axios';

const API_URL = 'https://countriesnow.space/api/v0.1';

export const getCountries = async () => {
    try {
        const response = await axios.get(`${API_URL}/countries/codes`);
        if (response.data && response.data.data) {
            // Format data to include dial codes and names
            return response.data.data.map(country => ({
                name: country.name,
                code: country.dial_code,
                isoCode: country.code,
                display: `${country.name} (${country.dial_code})`
            })).sort((a, b) => a.name.localeCompare(b.name));
        }
        // Fallback for when API fails, include at least Turkey
        return [{
            name: 'Turkey',
            code: '+90',
            isoCode: 'TR',
            display: 'Turkey (+90)'
        }];
    } catch (error) {
        console.error('Error fetching countries:', error);
        // Return Turkey as fallback
        return [{
            name: 'Turkey',
            code: '+90',
            isoCode: 'TR',
            display: 'Turkey (+90)'
        }];
    }
};

export default {
    getCountries
};
